name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  test:
    runs-on: ubuntu-24.04
    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_USER: visitflow
          POSTGRES_PASSWORD: visitflow
          POSTGRES_DB: visitflow
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U visitflow"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 10
    steps:
      - uses: actions/checkout@v6
      - uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v6
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: web/package-lock.json
      - name: Go tests and vet
        env:
          # The integration suite creates and drops a database per test, so it
          # needs an account that may run CREATE DATABASE.
          VISITFLOW_TEST_DSN: postgres://visitflow:visitflow@127.0.0.1:5432/visitflow?sslmode=disable
        run: |
          go test ./... -count=1
          go vet ./...
      - name: React production build
        working-directory: web
        run: |
          npm ci
          npm test
          npm run build
      - name: Docker image build
        run: docker build --build-arg VERSION=ci --build-arg COMMIT="$GITHUB_SHA" --build-arg BUILT_AT=ci -t visitflow:ci .

  e2e:
    runs-on: ubuntu-24.04
    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_USER: visitflow
          POSTGRES_PASSWORD: visitflow
          POSTGRES_DB: visitflow
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U visitflow"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 10
    env:
      VISITFLOW_E2E_ADMIN: admin
      VISITFLOW_E2E_PASSWORD: e2e-bootstrap-password
    steps:
      - uses: actions/checkout@v6
      - uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v6
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: web/package-lock.json
      - name: Install web dependencies
        working-directory: web
        run: npm ci
      - name: Build embedded UI
        working-directory: web
        run: npm run build
      - name: Build server with the real UI
        run: |
          rm -rf cmd/visitflow/webdist
          mkdir -p cmd/visitflow/webdist
          cp -r web/dist/. cmd/visitflow/webdist/
          go build -o visitflow ./cmd/visitflow
      - name: Start VisitFlow
        env:
          POSTGRES_DSN: postgres://visitflow:visitflow@127.0.0.1:5432/visitflow?sslmode=disable
          BOOTSTRAP_ADMIN: admin
          BOOTSTRAP_ADMIN_PASSWORD: e2e-bootstrap-password
        run: |
          # Redirect the log so the server is not killed by SIGPIPE when this
          # step's shell exits and the pipe closes.
          ENCRYPTION_KEY="$(openssl rand -base64 32)" nohup ./visitflow > visitflow.log 2>&1 &
          for attempt in $(seq 1 30); do
            if curl -fsS http://127.0.0.1:8080/readyz > /dev/null; then exit 0; fi
            sleep 2
          done
          echo "VisitFlow did not become ready" >&2
          cat visitflow.log >&2 || true
          exit 1
      - name: Install Playwright browser
        working-directory: web
        run: npx playwright install --with-deps chromium
      - name: Browser end-to-end tests
        working-directory: web
        run: npm run test:e2e
      - uses: actions/upload-artifact@v4
        if: failure()
        with:
          name: playwright-report
          path: web/playwright-report
          retention-days: 7
name: Release offline Docker image

on:
  push:
    tags:
      - "v*.*.*"

permissions:
  contents: write

jobs:
  release:
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@v6
      - uses: docker/setup-buildx-action@v4
      - name: Build offline image
        env:
          VERSION: ${{ github.ref_name }}
          COMMIT: ${{ github.sha }}
        run: |
          version="${VERSION#v}"
          built_at="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
          docker buildx build --load --platform linux/amd64 \
            --build-arg "VERSION=${version}" \
            --build-arg "COMMIT=${COMMIT}" \
            --build-arg "BUILT_AT=${built_at}" \
            -t "visitflow:v${version}" \
            -t "visitflow:latest" .
          docker save "visitflow:v${version}" "visitflow:latest" | gzip -9 > "visitflow-v${version}.tar.gz"
      - name: Verify image archive
        env:
          VERSION: ${{ github.ref_name }}
        run: |
          test -s "visitflow-${VERSION}.tar.gz"
          gzip -t "visitflow-${VERSION}.tar.gz"
      - name: Create GitHub release with image only
        env:
          GH_TOKEN: ${{ github.token }}
          VERSION: ${{ github.ref_name }}
        run: |
          gh release create "$VERSION" \
            "visitflow-${VERSION}.tar.gz" \
            --verify-tag \
            --generate-notes \
            --title "VisitFlow ${VERSION}"
/// <reference types="vitest/config" />
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  test: {
    // Unit tests live beside the source; the Playwright suites under e2e/ and
    // screenshots/ use the same .spec.ts suffix and must not be picked up here.
    include: ["src/**/*.test.ts"],
  },
  server: {
    proxy: { "/api": "http://localhost:8080", "/mcp": "http://localhost:8080" },
  },
  build: {
    sourcemap: false,
    target: "es2022",
    chunkSizeWarningLimit: 600,
    rollupOptions: {
      output: {
        // Vendor code changes far less often than the app, so it gets its own
        // long-lived, immutable chunk.
        manualChunks: {
          react: ["react", "react-dom", "react-router-dom"],
          mui: ["@mui/material", "@emotion/react", "@emotion/styled", "@emotion/cache"],
        },
      },
    },
  },
});
import { defineConfig, devices } from "@playwright/test";

// The end-to-end suite drives a real VisitFlow instance: the lobby flows depend
// on camera permissions, keyboard-wedge scanners and server-verified QR codes,
// none of which a component test can stand in for.
export default defineConfig({
  testDir: "./e2e",
  timeout: 60_000,
  expect: { timeout: 10_000 },
  fullyParallel: false,
  workers: 1,
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? [["list"], ["html", { open: "never" }]] : "list",
  use: {
    baseURL: process.env.VISITFLOW_BASE_URL ?? "http://127.0.0.1:8080",
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    locale: "ko-KR",
    timezoneId: "Asia/Seoul",
  },
  // Unset means Playwright's own bundled browser, which is what CI installs.
  // A machine that only has a system Chrome sets the channel instead; the key
  // is omitted rather than set to undefined so the default path is untouched.
  projects: [
    {
      name: "chromium",
      use: {
        ...devices["Desktop Chrome"],
        ...(process.env.VISITFLOW_E2E_BROWSER_CHANNEL
          ? { channel: process.env.VISITFLOW_E2E_BROWSER_CHANNEL }
          : {}),
      },
    },
  ],
});
import { useCallback, useEffect, useState } from "react";
import { Alert, Box, Button, Card, CardContent, Chip, Dialog, DialogActions, DialogContent, DialogTitle, Paper, Stack, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, TextField, Typography } from "@mui/material";
import CheckCircleOutlineRounded from "@mui/icons-material/CheckCircleOutlineRounded";
import HighlightOffRounded from "@mui/icons-material/HighlightOffRounded";
import { api, postJSON } from "../api";
import type { Visit, VisitDetailExtras } from "../types";
import { PageHeader } from "../components/AdminUI";
import { StatusChip } from "../components/StatusChip";

export function ApprovalsPage() {
  const [items, setItems] = useState<Visit[]>([]);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState("");
  type Participant = { id: string; name: string; phone: string; company?: string; title?: string; vehicle?: string; equipment?: string[]; status: string; consentSource?: string };
  const [review, setReview] = useState<{ visit: Visit; visitors: Participant[]; detail?: VisitDetailExtras } | null>(null);
  const [reason, setReason] = useState("");
  const openReview = async (visit: Visit) => { setReason(""); try { setReview(await api(`/api/v1/visits/${visit.id}`)); } catch (e) { setError(e instanceof Error ? e.message : "상세를 불러오지 못했습니다"); } };
  const decideFromReview = async (approve: boolean) => { if (!review) return; if (!approve && !reason.trim()) { setError("반려 사유를 입력하세요"); return; } setBusy(review.visit.id); setError(""); try { await postJSON(`/api/v1/visits/${review.visit.id}/${approve ? "approve" : "reject"}`, { reason }); setReview(null); await load(); } catch (e) { setError(e instanceof Error ? e.message : "승인 요청을 처리하지 못했습니다"); } finally { setBusy(""); } };
  const load = useCallback(async () => {
    try {
      const result = await api<{ items: Visit[] }>("/api/v1/visits?status=PENDING_APPROVAL&limit=200");
      setItems(result.items);
    } catch (e) { setError(e instanceof Error ? e.message : "승인 대기 목록을 불러오지 못했습니다"); }
  }, []);
  useEffect(() => { void load(); }, [load]);
  const decide = async (visit: Visit, approve: boolean) => {
    const reason = window.prompt(approve ? "승인 메모 (선택)" : "반려 사유를 입력하세요") ?? "";
    if (!approve && !reason.trim()) return;
    setBusy(visit.id); setError("");
    try {
      await postJSON(`/api/v1/visits/${visit.id}/${approve ? "approve" : "reject"}`, { reason });
      await load();
    } catch (e) { setError(e instanceof Error ? e.message : "승인 요청을 처리하지 못했습니다"); }
    finally { setBusy(""); }
  };
  return <Box sx={{ p: { xs: 2, md: 3 }, maxWidth: 1300, mx: "auto" }}>
    <PageHeader eyebrow="APPROVAL QUEUE" title="방문 승인" description="내 부서 또는 보안 권한 범위의 방문 요청을 검토합니다." />
    {error && <Alert severity="error" onClose={() => setError("")} sx={{ mb: 2 }}>{error}</Alert>}
    <Card><CardContent><TableContainer component={Paper} variant="outlined"><Table>
      <TableHead><TableRow><TableCell>방문 일시</TableCell><TableCell>방문자</TableCell><TableCell>담당자 · 장소</TableCell><TableCell>목적</TableCell><TableCell>상태</TableCell><TableCell align="right">결정</TableCell></TableRow></TableHead>
      <TableBody>{items.map((visit) => <TableRow key={visit.id} hover><TableCell sx={{ whiteSpace: "nowrap" }}>{new Date(visit.startAt).toLocaleString("ko-KR")}</TableCell><TableCell><Typography fontWeight={750}>{visit.primaryVisitor}{visit.visitorCount > 1 ? ` 외 ${visit.visitorCount - 1}명` : ""}</Typography><Typography variant="caption" color="text.secondary">{visit.company || "회사 미입력"}</Typography></TableCell><TableCell>{visit.hostName}<Typography variant="caption" display="block" color="text.secondary">{[visit.siteName, visit.lobbyName].filter(Boolean).join(" · ")}</Typography></TableCell><TableCell>{visit.purpose}{visit.visitTypeName && <Typography variant="caption" display="block" color="text.secondary">{visit.visitTypeName}</Typography>}</TableCell><TableCell><StatusChip status={visit.status} /></TableCell><TableCell align="right"><Stack direction="row" justifyContent="flex-end" spacing={1}><Button onClick={() => void openReview(visit)}>검토</Button><Button color="error" startIcon={<HighlightOffRounded />} disabled={busy === visit.id} onClick={() => void decide(visit, false)}>반려</Button><Button variant="contained" startIcon={<CheckCircleOutlineRounded />} disabled={busy === visit.id} onClick={() => void decide(visit, true)}>승인</Button></Stack></TableCell></TableRow>)}{items.length === 0 && <TableRow><TableCell colSpan={6} align="center" sx={{ py: 8 }}>승인 대기 중인 방문이 없습니다.</TableCell></TableRow>}</TableBody>
    </Table></TableContainer></CardContent></Card>
    <Dialog open={Boolean(review)} onClose={() => setReview(null)} fullWidth maxWidth="md"><DialogTitle>{review?.visit.requestNo} · 승인 검토</DialogTitle><DialogContent dividers>{review && <Stack spacing={2}><Box><Typography variant="h6">{review.visit.siteName}{review.visit.lobbyName ? ` · ${review.visit.lobbyName}` : ""} · {review.visit.purpose}</Typography><Typography color="text.secondary">{new Date(review.visit.startAt).toLocaleString("ko-KR")} – {new Date(review.visit.endAt).toLocaleString("ko-KR")} · 담당 {review.visit.hostName}{review.visit.departmentName ? ` (${review.visit.departmentName})` : ""}</Typography>{review.visit.visitTypeName && <Chip size="small" sx={{ mt: 1 }} label={review.visit.visitTypeName} />}</Box>{review.detail?.notes && <Alert severity="info" icon={false}>담당자 메모: {review.detail.notes}</Alert>}<TableContainer component={Paper} variant="outlined"><Table size="small"><TableHead><TableRow><TableCell>방문자</TableCell><TableCell>회사 · 직책</TableCell><TableCell>차량</TableCell><TableCell>반입 장비</TableCell><TableCell>동의</TableCell></TableRow></TableHead><TableBody>{review.visitors.map((p) => <TableRow key={p.id}><TableCell>{p.name}<Typography variant="caption" display="block" color="text.secondary">{p.phone}</Typography></TableCell><TableCell>{p.company || "-"}{p.title ? ` · ${p.title}` : ""}</TableCell><TableCell>{p.vehicle || "-"}</TableCell><TableCell>{(p.equipment ?? []).join(", ") || "-"}</TableCell><TableCell>{p.consentSource === "self" ? "본인" : "담당자 대행"}</TableCell></TableRow>)}</TableBody></Table></TableContainer><TextField label="승인 메모 / 반려 사유" value={reason} onChange={(e) => setReason(e.target.value)} helperText="반려 시 필수. 요청자에게 그대로 표시됩니다." /></Stack>}</DialogContent><DialogActions><Button onClick={() => setReview(null)}>닫기</Button><Button color="error" startIcon={<HighlightOffRounded />} disabled={busy !== ""} onClick={() => void decideFromReview(false)}>반려</Button><Button variant="contained" startIcon={<CheckCircleOutlineRounded />} disabled={busy !== ""} onClick={() => void decideFromReview(true)}>승인</Button></DialogActions></Dialog>
  </Box>;
}
import { useCallback, useEffect, useState } from "react";
import { Alert, Box, Button, Chip, Paper, Stack, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Typography } from "@mui/material";
import PrintRounded from "@mui/icons-material/PrintRounded";
import RefreshRounded from "@mui/icons-material/RefreshRounded";
import { api } from "../api";
import { PageHeader } from "../components/AdminUI";

export type RosterEntry = {
  site: string; lobby?: string; visitor: string; company?: string; phone?: string;
  host: string; department?: string; checkedInAt?: string; badgeNo?: string; placeDetail?: string;
};
type Roster = { generatedAt: string; count: number; items: RosterEntry[]; offline?: boolean };

const ROSTER_STORAGE_KEY = "visitflow_last_roster";

// The evacuation roster is printed and carried out of the building, so it keeps
// the last successful response in local storage: an outage during an emergency
// must not leave the lobby without a list.
function readCachedRoster(): Roster | null {
  try {
    const raw = window.localStorage.getItem(ROSTER_STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Roster) : null;
  } catch {
    return null;
  }
}

export function RosterPage() {
  const [roster, setRoster] = useState<Roster | null>(() => readCachedRoster());
  const [stale, setStale] = useState(false);
  const [error, setError] = useState("");
  const load = useCallback(async () => {
    try {
      const result = await api<Roster>("/api/v1/lobby/roster");
      setRoster(result);
      setStale(Boolean(result.offline));
      setError("");
      try { window.localStorage.setItem(ROSTER_STORAGE_KEY, JSON.stringify(result)); } catch { /* private mode */ }
    } catch (e) {
      setStale(true);
      setError(e instanceof Error ? e.message : "명단을 불러오지 못했습니다");
    }
  }, []);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { const timer = window.setInterval(() => void load(), 60000); return () => window.clearInterval(timer); }, [load]);

  const grouped = (roster?.items ?? []).reduce<Record<string, RosterEntry[]>>((acc, item) => {
    const key = `${item.site}${item.lobby ? ` · ${item.lobby}` : ""}`;
    (acc[key] ??= []).push(item);
    return acc;
  }, {});

  return <Box sx={{ p: { xs: 2, md: 3 }, maxWidth: 1200, mx: "auto", "@media print": { p: 0 } }}>
    <Box sx={{ "@media print": { display: "none" } }}>
      <PageHeader eyebrow="EMERGENCY" title="비상 대피 명단" description="현재 사내에 체류 중인 방문자를 사업장·로비별로 인쇄할 수 있습니다."
        actions={<><Button startIcon={<RefreshRounded />} onClick={() => void load()}>새로고침</Button><Button variant="contained" startIcon={<PrintRounded />} onClick={() => window.print()}>인쇄</Button></>} />
      {error && <Alert severity="warning" sx={{ mb: 2 }}>{error} · 마지막으로 받은 명단을 표시합니다.</Alert>}
      {stale && !error && <Alert severity="warning" sx={{ mb: 2 }}>오프라인 상태입니다. 마지막으로 동기화된 명단입니다.</Alert>}
    </Box>
    <Paper variant="outlined" sx={{ p: { xs: 2, md: 3 } }}>
      <Stack direction={{ xs: "column", sm: "row" }} justifyContent="space-between" alignItems={{ sm: "baseline" }} spacing={1} mb={2}>
        <Box>
          <Typography variant="h5">비상 대피 명단 · 현재 체류 방문자</Typography>
          <Typography variant="body2" color="text.secondary">
            기준 시각 {roster ? new Date(roster.generatedAt).toLocaleString("ko-KR") : "-"}
          </Typography>
        </Box>
        <Chip color="primary" label={`총 ${roster?.count ?? 0}명`} sx={{ fontWeight: 800 }} />
      </Stack>
      {Object.entries(grouped).map(([group, entries]) => <Box key={group} sx={{ mb: 3, breakInside: "avoid" }}>
        <Typography variant="subtitle1" fontWeight={800} sx={{ mb: 1 }}>{group} · {entries.length}명</Typography>
        <TableContainer><Table size="small"><TableHead><TableRow>
          <TableCell>방문자</TableCell><TableCell>회사</TableCell><TableCell>연락처</TableCell><TableCell>담당자 · 부서</TableCell><TableCell>입실</TableCell><TableCell>출입증</TableCell><TableCell>확인</TableCell>
        </TableRow></TableHead><TableBody>
          {entries.map((item, index) => <TableRow key={`${group}-${index}`}>
            <TableCell sx={{ fontWeight: 700 }}>{item.visitor}</TableCell>
            <TableCell>{item.company || "-"}</TableCell>
            <TableCell>{item.phone || "-"}</TableCell>
            <TableCell>{item.host}{item.department ? ` · ${item.department}` : ""}</TableCell>
            <TableCell>{item.checkedInAt ? new Date(item.checkedInAt).toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit" }) : "-"}</TableCell>
            <TableCell>{item.badgeNo || "-"}</TableCell>
            <TableCell sx={{ minWidth: 70 }}>☐</TableCell>
          </TableRow>)}
        </TableBody></Table></TableContainer>
      </Box>)}
      {(roster?.items.length ?? 0) === 0 && <Typography color="text.secondary" sx={{ py: 6, textAlign: "center" }}>현재 사내에 체류 중인 방문자가 없습니다.</Typography>}
    </Paper>
  </Box>;
}
#!/usr/bin/env bash
set -euo pipefail

# Runs the browser end-to-end suite against a real VisitFlow server that embeds
# the real `npm run build` output, the same way the CI `e2e` job does. The
# server hardcodes `:8080` (cmd/visitflow/main.go), so it runs in a container on
# a private network and the host port is assigned by the OS — nothing here binds
# a fixed port, and nothing touches containers, networks or images it did not
# create itself.
#
# "registers a site, a lobby and an organization from the admin console" has
# failed against hand-assembled local servers while passing in CI; it passes
# here, because every run gets a fresh database and a fresh server. The suite's
# exit code is reported verbatim either way and no spec is ever skipped.

if [[ $# -ne 0 ]]; then
  echo "usage: $0" >&2
  echo "  VISITFLOW_LOCAL_E2E_PORT      host port for the server (default: assigned by the OS)" >&2
  echo "  VISITFLOW_E2E_BROWSER_CHANNEL Playwright browser channel (default: auto-detected)" >&2
  exit 2
fi

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$repo_root"

for binary in docker node npm go curl; do
  if ! command -v "$binary" > /dev/null 2>&1; then
    echo "$binary is required but was not found in PATH" >&2
    exit 1
  fi
done

web_dist="$repo_root/cmd/visitflow/webdist"
work_dir="$(mktemp -d)"
# Unique so that concurrent runs, and the unrelated containers already on this
# host, cannot collide with or be removed by this one.
prefix="vf-local-e2e-$$-${RANDOM}"
network_created=""
started_containers=()

cleanup() {
  local keep_status=$?
  set +e
  # Restore the tracked webdist stub from the temporary copy first. Using
  # `git checkout --` here has cost uncommitted work in this repository before.
  if [[ -d "$work_dir/webdist-backup" ]]; then
    rm -rf "$web_dist"
    cp -a "$work_dir/webdist-backup" "$web_dist"
  fi
  local container
  for container in "${started_containers[@]+"${started_containers[@]}"}"; do
    docker rm --force --volumes "$container" > /dev/null 2>&1
  done
  if [[ -n "$network_created" ]]; then
    docker network rm "$network_created" > /dev/null 2>&1
  fi
  rm -rf "$work_dir"
  return "$keep_status"
}
trap cleanup EXIT INT TERM

echo "==> web dependencies"
if [[ ! -d "$repo_root/web/node_modules" ]]; then
  (cd "$repo_root/web" && npm ci)
fi

echo "==> production UI build"
(cd "$repo_root/web" && npm run build)

echo "==> embedding the build into cmd/visitflow/webdist"
cp -a "$web_dist" "$work_dir/webdist-backup"
rm -rf "$web_dist"
mkdir -p "$web_dist"
cp -r "$repo_root/web/dist/." "$web_dist/"

echo "==> server build"
CGO_ENABLED=0 go build -o "$work_dir/visitflow" ./cmd/visitflow

echo "==> PostgreSQL"
network_created="$prefix-net"
docker network create "$network_created" > /dev/null
started_containers+=("$prefix-pg")
docker run --detach \
  --name "$prefix-pg" \
  --network "$network_created" \
  --network-alias postgres \
  --env POSTGRES_USER=visitflow \
  --env POSTGRES_PASSWORD=visitflow \
  --env POSTGRES_DB=visitflow \
  postgres:16-alpine > /dev/null
for _ in $(seq 1 60); do
  if docker exec "$prefix-pg" pg_isready --username visitflow > /dev/null 2>&1; then
    break
  fi
  sleep 1
done
if ! docker exec "$prefix-pg" pg_isready --username visitflow > /dev/null 2>&1; then
  echo "PostgreSQL did not become ready" >&2
  docker logs "$prefix-pg" >&2 || true
  exit 1
fi

echo "==> VisitFlow server"
# An empty host port lets the OS pick a free one; 8080 is routinely taken by
# another project on a developer machine.
host_port_spec="127.0.0.1:${VISITFLOW_LOCAL_E2E_PORT-}:8080"
admin_user="${VISITFLOW_E2E_ADMIN:-admin}"
admin_password="${VISITFLOW_E2E_PASSWORD:-e2e-bootstrap-password}"
started_containers+=("$prefix-app")
docker run --detach \
  --name "$prefix-app" \
  --network "$network_created" \
  --publish "$host_port_spec" \
  --volume "$work_dir/visitflow:/usr/local/bin/visitflow:ro" \
  --env "POSTGRES_DSN=postgres://visitflow:visitflow@postgres:5432/visitflow?sslmode=disable" \
  --env "BOOTSTRAP_ADMIN=$admin_user" \
  --env "BOOTSTRAP_ADMIN_PASSWORD=$admin_password" \
  --env "ENCRYPTION_KEY=$(node -e 'process.stdout.write(require("crypto").randomBytes(32).toString("base64"))')" \
  debian:12-slim /usr/local/bin/visitflow > /dev/null

host_port="$(docker port "$prefix-app" 8080/tcp | head -1)"
host_port="${host_port##*:}"
if [[ -z "$host_port" ]]; then
  echo "could not resolve the published host port" >&2
  exit 1
fi
base_url="http://127.0.0.1:$host_port"

for _ in $(seq 1 60); do
  if curl --fail --silent --show-error "$base_url/readyz" > /dev/null 2>&1; then
    break
  fi
  sleep 1
done
if ! curl --fail --silent --show-error "$base_url/readyz" > /dev/null 2>&1; then
  echo "VisitFlow did not become ready at $base_url" >&2
  docker logs "$prefix-app" >&2 || true
  exit 1
fi

echo "==> browser"
browser_note="Playwright's bundled chromium"
if [[ -n "${VISITFLOW_E2E_BROWSER_CHANNEL+set}" ]]; then
  browser_note="channel '${VISITFLOW_E2E_BROWSER_CHANNEL}' (from the environment)"
elif (cd "$repo_root/web" && node -e '
  require("@playwright/test").chromium.launch()
    .then((browser) => browser.close())
    .catch(() => process.exit(1));
' > /dev/null 2>&1); then
  : # The bundled browser is installed, so behave exactly like CI.
elif command -v google-chrome > /dev/null 2>&1; then
  # No bundled download on this machine, but a system Chrome is installed.
  export VISITFLOW_E2E_BROWSER_CHANNEL=chrome
  browser_note="channel 'chrome' (no bundled browser installed)"
else
  (cd "$repo_root/web" && npx playwright install chromium)
fi
echo "using $browser_note"

echo "==> npm run test:e2e against $base_url"
suite_status=0
(cd "$repo_root/web" && VISITFLOW_BASE_URL="$base_url" VISITFLOW_E2E_ADMIN="$admin_user" \
  VISITFLOW_E2E_PASSWORD="$admin_password" npm run test:e2e) || suite_status=$?

if [[ "$suite_status" -eq 0 ]]; then
  echo "playwright: passed (base URL $base_url, $browser_note)"
else
  echo "playwright: failed with exit code $suite_status (base URL $base_url, $browser_note)"
fi
exit "$suite_status"

