func passTokenFrom(t *testing.T, created map[string]any) string {
	t.Helper()
	urls, _ := created["passUrls"].([]any)
	if len(urls) == 0 {
		t.Fatalf("visit did not return a pass url: %v", created)
	}
	value := fmt.Sprint(urls[0])
	index := strings.LastIndex(value, "/q/")
	if index < 0 {
