	env := newTestEnv(t)
	created := env.json(http.MethodPost, "/api/v1/visits", visitBody(env.siteID(), nil), http.StatusCreated)
	visitID := fmt.Sprint(created["id"])
	detail := env.json(http.MethodGet, "/api/v1/visits/"+visitID, nil, http.StatusOK)
