		"name": "Kim Visitor", "company": "테스트상사", "locale": "en", "consent": true,
	}, http.StatusOK)

	reused := public.do(http.MethodPost, "/api/v1/public/registrations/"+token, map[string]any{"name": "Kim Visitor", "consent": true})
