	if extras := rejected["detail"].(map[string]any); extras["approvalReason"] != "일정 중복" || extras["approverName"] == "" {
		t.Fatalf("rejection reason or approver missing from detail: %v", extras)
	}
	if summary := rejected["visit"].(map[string]any); summary["approvalReason"] != "일정 중복" {
		t.Fatalf("summary lacks the rejection reason: %v", summary)
	}
}
		if err != nil {
			return nil, errors.New("XLSX 첫 번째 워크시트를 읽을 수 없습니다")
		}
		return rows, nil
	default:
		return nil, errors.New("지원 파일 형식은 .csv와 .xlsx입니다")
	}
}

// decodeSpreadsheetText normalises what Excel actually produces. Korean Windows
// saves "CSV (쉼표로 분리)" in CP949, not UTF-8, so a file exported from Excel
// arrived as mojibake and failed with "이름(name) 열이 필요합니다" even though the
// column was there. A UTF-8 byte-order mark is stripped for the same reason.
func decodeSpreadsheetText(data []byte) []byte {
	data = bytes.TrimPrefix(data, []byte{0xEF, 0xBB, 0xBF})
	if utf8.Valid(data) {
		return data
    const reason = window.prompt(approve ? "승인 메모 (선택)" : "반려 사유를 입력하세요") ?? "";
    if (!approve && !reason.trim()) return;
    setBusy(visit.id); setError("");
    try {
      await postJSON(`/api/v1/visits/${visit.id}/${approve ? "approve" : "reject"}`, { reason });
      await load();
    } catch (e) { setError(e instanceof Error ? e.message : "승인 요청을 처리하지 못했습니다"); }
    finally { setBusy(""); }
  };
  return <Box sx={{ p: { xs: 2, md: 3 }, maxWidth: 1300, mx: "auto" }}>
    <PageHeader eyebrow="APPROVAL QUEUE" title="방문 승인" description="내 부서 또는 보안 권한 범위의 방문 요청을 검토합니다." />
    {error && <Alert severity="error" onClose={() => setError("")} sx={{ mb: 2 }}>{error}</Alert>}
    <Card><CardContent><TableContainer component={Paper} variant="outlined"><Table>
      <TableHead><TableRow><TableCell>방문 일시</TableCell><TableCell>방문자</TableCell><TableCell>담당자 · 장소</TableCell><TableCell>목적</TableCell><TableCell>상태</TableCell><TableCell align="right">결정</TableCell></TableRow></TableHead>
